<script setup lang="ts">
import DecorationReferenceStyle from './DecorationReferenceStyle.vue'
import type {DecorationBlock,DecorationAppearance,DecorationOptions,DecorationTheme} from '../../../../api/src/core/decoration-types'
import {decorationAppearance,decorationTheme} from '../../../../api/src/core/decoration-contract.mjs'
import {decorationOptions,galleryImageFit} from '../../../../api/src/core/decoration-options.mjs'
import DecorationSettingRange from './DecorationSettingRange.vue'
import DecorationColorField from './DecorationColorField.vue'
import ImageSelectTile from './ImageSelectTile.vue'
const props=defineProps<{disabled?:boolean;theme?:DecorationTheme;imageUrl:(id:string)=>string}>()
const block=defineModel<DecorationBlock>({required:true})
defineEmits<{pickBackground:[]}>()
const a=computed(()=>{const raw=decorationAppearance(block.value),theme=decorationTheme({theme:props.theme});return block.value.inheritTheme!==false?{...raw,radius:theme.radius,fontSize:theme.fontSize,gap:theme.spacing}:raw}),o=computed(()=>decorationOptions(block.value))
function setA(key:keyof DecorationAppearance,value:unknown){if(!props.disabled)block.value.appearance={...a.value,[key]:value}}
function setO(key:keyof DecorationOptions,value:unknown){if(!props.disabled)block.value.options={...o.value,[key]:value}}
const margins=[{key:'marginTop',label:'上边距',min:-100,fallback:0},{key:'marginBottom',label:'下边距',min:-100,fallback:12},{key:'marginHorizontal',label:'左右边距',min:0,fallback:0}] as const
const padding=[{key:'paddingTop',label:'上内边距'},{key:'paddingBottom',label:'下内边距'},{key:'paddingHorizontal',label:'左右内边距'}] as const
</script>
<template><div class="block-style-panel">
<section v-if="block.type==='assets'">
 <h3>资产布局</h3><UFormField label="展示样式"><USelect :model-value="o.assetLayout" :items="[{label:'双卡片',value:'cards'},{label:'简洁分栏',value:'strip'},{label:'纵向列表',value:'list'}]" :disabled="disabled" class="w-full" aria-label="资产展示样式" @update:model-value="setO('assetLayout',$event)"/></UFormField>
 <label class="style-switch"><span>显示资产图标</span><USwitch :model-value="o.assetIcons" :disabled="disabled" aria-label="显示资产图标" @update:model-value="setO('assetIcons',$event)"/></label>
 <DecorationSettingRange label="数字字号" :model-value="o.assetValueSize" :min="18" :max="40" :disabled="disabled" @update:model-value="setO('assetValueSize',$event)"/>
 <DecorationSettingRange label="名称字号" :model-value="o.assetLabelSize" :min="10" :max="18" :disabled="disabled" @update:model-value="setO('assetLabelSize',$event)"/>
 <template v-if="o.assetLayout!=='strip'"><DecorationSettingRange label="卡片间距" :model-value="o.assetGap" :min="0" :max="24" :disabled="disabled" @update:model-value="setO('assetGap',$event)"/><DecorationSettingRange label="卡片圆角" :model-value="o.assetRadius" :min="0" :max="28" :disabled="disabled" @update:model-value="setO('assetRadius',$event)"/></template>
 <h3>资产配色</h3><label class="style-switch"><span>卡片配色跟随主题</span><USwitch :model-value="o.assetTheme" :disabled="disabled" aria-label="资产配色跟随主题" @update:model-value="setO('assetTheme',$event)"/></label>
 <template v-if="!o.assetTheme"><DecorationColorField :model-value="o.assetAccent" label="强调颜色" :disabled="disabled" @update:model-value="setO('assetAccent',$event)"/><DecorationColorField v-if="o.assetLayout!=='strip'" :model-value="o.assetSurface" label="卡片背景" :disabled="disabled" @update:model-value="setO('assetSurface',$event)"/><DecorationColorField :model-value="o.assetText" label="数字与标题" :disabled="disabled" @update:model-value="setO('assetText',$event)"/><DecorationColorField :model-value="o.assetMuted" label="辅助文字" :disabled="disabled" @update:model-value="setO('assetMuted',$event)"/></template>
</section><DecorationReferenceStyle v-model="block" :disabled="disabled" :image-url="imageUrl"/><section v-if="!['membership','member-level','member-overview'].includes(block.type)"><label class="style-switch"><span>跟随主题</span><USwitch v-model="block.inheritTheme" :disabled="disabled" aria-label="组件跟随主题"/></label><p v-if="block.inheritTheme">颜色、基础字号、组件圆角和默认间距跟随主题；下面的独立设置仍可调整。</p></section>
<section v-if="block.type==='collection'"><h3>卡片样式</h3><DecorationSettingRange label="卡片宽度" :model-value="o.collectionWidth||71" :min="60" :max="240" :disabled="disabled" @update:model-value="setO('collectionWidth',$event)"/><DecorationSettingRange label="图片高度" :model-value="o.collectionImageHeight||77" :min="40" :max="320" :disabled="disabled" @update:model-value="setO('collectionImageHeight',$event)"/></section><section v-if="block.type==='gallery'"><h3>魔方样式</h3><DecorationSettingRange label="魔方高度" :model-value="o.galleryHeight||0" :max="400" :disabled="disabled" @update:model-value="setO('galleryHeight',$event)"/><p>0 表示按图片比例自动计算高度。</p><UFormField label="图片填充"><USelect :model-value="galleryImageFit(block)" :items="[{label:'完整显示图片',value:'contain'},{label:'等比裁切填满',value:'cover'}]" :disabled="disabled" class="w-full" @update:model-value="setO('imageFit',$event)"/></UFormField><DecorationSettingRange label="图片间距" :model-value="o.imageGap" :max="30" :disabled="disabled" @update:model-value="setO('imageGap',$event)"/><DecorationSettingRange label="图片上圆角" :model-value="o.imageRadiusTop" :max="50" :disabled="disabled" @update:model-value="setO('imageRadiusTop',$event)"/><DecorationSettingRange label="图片下圆角" :model-value="o.imageRadiusBottom" :max="50" :disabled="disabled" @update:model-value="setO('imageRadiusBottom',$event)"/></section>
<section v-if="block.type==='links'&&o.navMode!=='text'"><h3>图片设置</h3><DecorationSettingRange label="图片尺寸" :model-value="o.iconSize" :min="20" :max="60" :disabled="disabled" @update:model-value="setO('iconSize',$event)"/><DecorationSettingRange label="图片圆角" :model-value="o.iconRadius" :max="50" :disabled="disabled" @update:model-value="setO('iconRadius',$event)"/></section>
<section v-if="block.type==='links'||block.type==='notice'"><h3>文字设置</h3><DecorationSettingRange label="文字字号" :model-value="o.labelSize" :min="12" :max="20" :disabled="disabled" @update:model-value="setO('labelSize',$event)"/><div class="style-field"><span>文字粗细</span><div class="style-choices"><button v-for="entry in [{key:'normal',label:'常规'},{key:'bold',label:'加粗'}]" :key="entry.key" type="button" :class="{active:o.labelWeight===entry.key}" :disabled="disabled" @click="setO('labelWeight',entry.key)">{{entry.label}}</button></div></div><DecorationColorField :model-value="o.labelColor" label="文字颜色" :disabled="disabled" @update:model-value="setO('labelColor',$event)"/></section>
<section v-if="block.type==='search'||block.type==='links'&&o.navDisplay==='pages'"><h3>指示器设置</h3><div class="style-field"><span>指示器样式</span><div class="style-choices"><button v-for="entry in [{key:'dots',label:'圆点'},{key:'bars',label:'短线'},{key:'elongated',label:'长圆点'}]" :key="entry.key" type="button" :class="{active:o.indicatorStyle===entry.key}" :disabled="disabled" @click="setO('indicatorStyle',entry.key)">{{entry.label}}</button></div></div><div class="style-choices"><button v-for="entry in [{key:'left',label:'居左'},{key:'center',label:'居中'},{key:'right',label:'居右'}]" :key="entry.key" type="button" :class="{active:o.indicatorAlign===entry.key}" :disabled="disabled" @click="setO('indicatorAlign',entry.key)">{{entry.label}}</button></div><DecorationColorField :model-value="o.indicatorColor" label="默认颜色" :disabled="disabled" @update:model-value="setO('indicatorColor',$event)"/><DecorationColorField :model-value="o.indicatorActiveColor" label="选中颜色" :disabled="disabled" @update:model-value="setO('indicatorActiveColor',$event)"/></section>
<section><h3>底部背景</h3><label class="style-switch"><span>设置底部背景</span><USwitch :model-value="!!a.outerBackground" :disabled="disabled" @update:model-value="setA('outerBackground',$event?'#ffffff':null);!$event&&setA('outerBackgroundEnd',null)"/></label><template v-if="a.outerBackground"><DecorationColorField :model-value="a.outerBackground" label="底部背景颜色" :disabled="disabled" @update:model-value="setA('outerBackground',$event)"/><label class="style-switch"><span>渐变</span><USwitch :model-value="!!a.outerBackgroundEnd" :disabled="disabled" @update:model-value="setA('outerBackgroundEnd',$event?a.outerBackground:null)"/></label><DecorationColorField v-if="a.outerBackgroundEnd" :model-value="a.outerBackgroundEnd" label="底部渐变末色" :disabled="disabled" @update:model-value="setA('outerBackgroundEnd',$event)"/></template></section><section v-if="!['membership','member-level','member-overview'].includes(block.type)"><h3>组件背景</h3><label class="style-switch"><span>透明背景</span><USwitch :model-value="a.transparent===true" :disabled="disabled" @update:model-value="setA('transparent',$event)"/></label><DecorationColorField v-model="block.background" label="背景颜色" :disabled="disabled||block.inheritTheme"/><label class="style-switch"><span>渐变背景</span><USwitch :model-value="!!a.backgroundEnd" :disabled="disabled" @update:model-value="setA('backgroundEnd',$event?block.background:null)"/></label><template v-if="a.backgroundEnd"><DecorationColorField :model-value="a.backgroundEnd" label="渐变末色" :disabled="disabled" @update:model-value="setA('backgroundEnd',$event)"/><div class="style-choices"><button type="button" :class="{active:a.backgroundDirection!=='to right'}" @click="setA('backgroundDirection','to bottom')">从上到下</button><button type="button" :class="{active:a.backgroundDirection==='to right'}" @click="setA('backgroundDirection','to right')">从左到右</button></div></template><div class="style-field"><span>背景图片</span><ImageSelectTile :src="a.backgroundImageId?imageUrl(a.backgroundImageId):null" label="组件背景图片" :disabled="disabled" :removable="!!a.backgroundImageId" @select="$emit('pickBackground')" @remove="setA('backgroundImageId',null)"/></div><DecorationSettingRange v-if="a.backgroundImageId" label="背景遮罩" :model-value="a.backgroundOverlay||0" unit="%" :disabled="disabled" @update:model-value="setA('backgroundOverlay',$event)"/></section>
<section><h3>间距与留白</h3><DecorationSettingRange v-for="f in margins" :key="f.key" :label="f.label" :model-value="a[f.key]??(f.key==='marginBottom'?a.gap:f.fallback)" :min="f.min" :disabled="disabled" @update:model-value="setA(f.key,$event)"/><DecorationSettingRange v-for="f in padding" :key="f.key" :label="f.label" :model-value="a[f.key]??a.padding" :disabled="disabled" @update:model-value="setA(f.key,$event)"/></section>
<section v-if="!['membership','member-level','member-overview'].includes(block.type)"><h3>组件圆角</h3><DecorationSettingRange label="上圆角" :model-value="a.radiusTop??a.radius" :disabled="disabled" @update:model-value="setA('radiusTop',$event)"/><DecorationSettingRange label="下圆角" :model-value="a.radiusBottom??a.radius" :disabled="disabled" @update:model-value="setA('radiusBottom',$event)"/></section>
<section v-if="!['membership','member-level','member-overview','links','notice','gallery','banner','image','spacer'].includes(block.type)"><h3>文字排版</h3><DecorationColorField v-model="block.color" label="文字颜色" :disabled="disabled||block.inheritTheme"/><DecorationSettingRange label="基础字号" :model-value="a.fontSize" :min="12" :max="32" :disabled="disabled||block.inheritTheme" @update:model-value="setA('fontSize',$event)"/><DecorationSettingRange label="行高" :model-value="a.lineHeight||1.5" :min="1" :max="3" :step=".1" unit="倍" :disabled="disabled" @update:model-value="setA('lineHeight',$event)"/><div class="style-choices"><button type="button" :class="{active:a.fontWeight!=='bold'}" :disabled="disabled" @click="setA('fontWeight','normal')">常规</button><button type="button" :class="{active:a.fontWeight==='bold'}" :disabled="disabled" @click="setA('fontWeight','bold')">加粗</button></div></section>
<section v-if="!['membership','member-level','member-overview'].includes(block.type)"><h3>内容对齐</h3><div class="style-choices"><button v-for="entry in [{key:'left',label:'左对齐'},{key:'center',label:'居中'},{key:'right',label:'右对齐'}]" :key="entry.key" type="button" :class="{active:block.align===entry.key}" :disabled="disabled" @click="block.align=entry.key as 'left'|'center'|'right'">{{entry.label}}</button></div></section>
</div></template>
<style scoped>.block-style-panel{display:grid;gap:24px}.block-style-panel section{display:grid;gap:16px}.block-style-panel section+section{border-top:1px solid var(--ui-border);padding-top:22px}.block-style-panel h3{font-size:13px;font-weight:600}.block-style-panel p{font-size:11px;line-height:1.7;color:var(--ui-text-muted)}.style-switch{display:flex;justify-content:space-between;align-items:center;font-size:12px}.style-field{display:grid;gap:10px;font-size:12px}.style-choices{display:flex;gap:8px;flex-wrap:wrap}.style-choices button{font-size:12px;padding:7px 12px;border:1px solid var(--ui-border);border-radius:5px}.style-choices button.active{color:var(--ui-primary);border-color:var(--ui-primary);background:color-mix(in srgb,var(--ui-primary) 5%,var(--ui-bg))}</style>
